import React from 'react';
import data from './../data/experienceData.js';
import { FaBriefcase, FaMapMarkerAlt, FaCalendarAlt, FaCode, FaRocket, FaStar } from 'react-icons/fa';

function Experience() {
  return (
    <section id="experience" className='py-20 px-6 sm:px-8 lg:px-12 relative overflow-hidden'>
      {/* Enhanced Background */}
      <div className="absolute inset-0 bg-gradient-to-br from-[#0F1419] via-[#1A1D23] to-[#0F1419]"></div>
      <div className="absolute top-1/6 left-1/4 w-80 h-80 bg-[#3B82F6]/6 rounded-full blur-3xl animate-pulse-subtle"></div>
      <div className="absolute bottom-1/5 right-1/5 w-72 h-72 bg-[#60A5FA]/4 rounded-full blur-2xl animate-float"></div>

      {/* Floating particles */}
      <div className="absolute top-1/4 right-1/6 w-1.5 h-1.5 bg-[#3B82F6] rounded-full animate-float opacity-40"></div>
      <div className="absolute bottom-1/3 left-1/5 w-1 h-1 bg-[#60A5FA] rounded-full animate-pulse-subtle opacity-50"></div>
      <div className="absolute top-2/3 right-1/3 w-2 h-2 bg-[#3B82F6] rounded-full animate-pulse-subtle opacity-30"></div>

      <div className="max-w-7xl mx-auto relative z-10">
        {/* Enhanced Section Header */}
        <div className="text-center mb-20 animate-fade-in-up">
          <h2 className="text-3xl sm:text-4xl md:text-5xl font-bold text-white mb-6">
            My <span className="text-gradient bg-gradient-to-r from-[#3B82F6] to-[#60A5FA] bg-clip-text text-transparent">Journey</span>
          </h2>
          <div className="w-24 h-1 bg-gradient-to-r from-[#3B82F6] to-[#60A5FA] mx-auto rounded-full shadow-lg"></div>
          <p className="text-gray-300 text-lg max-w-3xl mx-auto leading-relaxed mt-6">
            My professional path, growth milestones, and the experiences that shaped my expertise
          </p>
        </div>

        {/* Modern Timeline Layout */}
        <div className="relative">
          {/* Main timeline line with gradient */}
          <div className="hidden lg:block absolute left-1/2 top-0 transform -translate-x-1/2 h-full w-1">
            <div className="h-full w-full bg-gradient-to-b from-[#3B82F6] via-[#60A5FA] to-[#3B82F6]/20 rounded-full shadow-lg"></div>
          </div>

          {/* Experience Cards */}
          {data.map((exp, index) => (
            <ModernExperienceCard key={exp.id} experience={exp} index={index} />
          ))}
        </div>
      </div>
    </section>
  );
}

// Completely redesigned Experience Card
function ModernExperienceCard({ experience, index }) {
  const isEven = index % 2 === 0;
  const cardPosition = isEven ? 'lg:pr-8 lg:text-right' : 'lg:pl-8 lg:text-left';
  const animateClass = isEven ? 'animate-fade-in-left' : 'animate-fade-in-right';
  const flexDirection = isEven ? 'lg:justify-start' : 'lg:justify-end';

  return (
    <div className={`relative mb-16 lg:mb-24 flex w-full ${flexDirection}`}>
      {/* Timeline Node - Central focal point */}
      <div className="hidden lg:flex lg:absolute lg:left-1/2 lg:transform lg:-translate-x-1/2 lg:top-8 flex-col items-center z-20">
        <div className="relative">
          {/* Outer ring with animation */}
          <div className="absolute inset-0 w-6 h-6 rounded-full bg-gradient-to-r from-[#3B82F6] to-[#60A5FA] animate-pulse-subtle"></div>
          {/* Inner dot */}
          <div className="relative w-6 h-6 rounded-full bg-[#0F1419] border-4 border-[#3B82F6] shadow-lg flex items-center justify-center">
            <div className="w-2 h-2 rounded-full bg-[#3B82F6]"></div>
          </div>
          {/* Floating accent */}
          <div className="absolute -top-1 -right-1 w-3 h-3 rounded-full bg-[#60A5FA]/60 animate-pulse"></div>
        </div>
      </div>

      {/* Experience Card */}
      <div className={`relative w-full lg:w-5/12 ${cardPosition}`}>
        <div className={`glass-effect-strong p-8 rounded-2xl hover:shadow-glow transition-all duration-500 group ${animateClass}`} 
             style={{ animationDelay: `${index * 0.2}s` }}>

          {/* Card Header with Modern Layout */}
          <div className="mb-6">
            <div className="flex items-start justify-between mb-4">
              <div className="flex-1">
                <h3 className="text-xl sm:text-2xl font-bold text-white mb-2 group-hover:text-gradient transition-colors duration-300">
                  {experience.title}
                </h3>
                <div className="flex items-center gap-2 mb-3">
                  <div className="w-8 h-8 bg-gradient-to-r from-[#3B82F6] to-[#60A5FA] rounded-lg flex items-center justify-center">
                    <FaBriefcase className="text-white text-sm" />
                  </div>
                  <span className="text-[#3B82F6] font-semibold text-lg">{experience.org}</span>
                </div>
              </div>

              {/* Status Badge */}
              <div className={`px-4 py-2 rounded-full text-sm font-medium shadow-lg ${
                experience.type === 'Full-time' ? 'bg-gradient-to-r from-green-500/20 to-green-400/20 text-green-400 border border-green-400/30' :
                experience.type === 'Internship' ? 'bg-gradient-to-r from-[#3B82F6]/20 to-[#60A5FA]/20 text-[#3B82F6] border border-[#3B82F6]/30' :
                'bg-gradient-to-r from-purple-500/20 to-purple-400/20 text-purple-400 border border-purple-400/30'
              }`}>
                {experience.type}
              </div>
            </div>

            {/* Meta Information */}
            <div className="flex flex-wrap gap-4 text-sm text-gray-400">
              <div className="flex items-center gap-2">
                <FaCalendarAlt className="text-[#3B82F6]" />
                <span>{experience.date}</span>
              </div>
              <div className="flex items-center gap-2">
                <FaMapMarkerAlt className="text-[#3B82F6]" />
                <span>{experience.location}</span>
              </div>
            </div>
          </div>

          {/* Description with better typography */}
          <div className="mb-6">
            <p className="text-gray-300 text-base leading-relaxed">
              {experience.description}
            </p>
          </div>

          {/* Enhanced Responsibilities Section */}
          <div className="mb-6">
            <h4 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <FaRocket className="text-[#3B82F6]" />
              Key Responsibilities
            </h4>
            <div className="space-y-3">
              {experience.responsibilities.map((resp, idx) => (
                <div key={idx} className="flex items-start gap-3 group/item">
                  <div className="w-2 h-2 bg-[#3B82F6] rounded-full mt-2 flex-shrink-0 group-hover/item:scale-125 transition-transform duration-200"></div>
                  <span className="text-gray-300 text-sm leading-relaxed">{resp}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Enhanced Achievements Section */}
          <div className="mb-6">
            <h4 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <FaStar className="text-[#60A5FA]" />
              Key Achievements
            </h4>
            <div className="space-y-3">
              {experience.achievements.map((achievement, idx) => (
                <div key={idx} className="flex items-start gap-3 group/item">
                  <div className="w-2 h-2 bg-[#60A5FA] rounded-full mt-2 flex-shrink-0 group-hover/item:scale-125 transition-transform duration-200"></div>
                  <span className="text-gray-300 text-sm leading-relaxed">{achievement}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Enhanced Technologies Section */}
          <div>
            <h4 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <FaCode className="text-[#3B82F6]" />
              Technologies & Tools
            </h4>
            <div className="flex flex-wrap gap-2">
              {experience.technologies.map((tech, idx) => (
                <span 
                  key={idx} 
                  className="px-3 py-2 bg-gradient-to-r from-[#3B82F6]/10 to-[#60A5FA]/10 text-[#3B82F6] rounded-lg text-sm font-medium border border-[#3B82F6]/20 hover:border-[#3B82F6]/40 hover:bg-[#3B82F6]/20 transition-all duration-300"
                >
                  {tech}
                </span>
              ))}
            </div>
          </div>

          {/* Decorative Corner Accent */}
          <div className="absolute top-4 right-4 w-8 h-8 border-r-2 border-t-2 border-[#3B82F6]/30 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
          <div className="absolute bottom-4 left-4 w-8 h-8 border-l-2 border-b-2 border-[#60A5FA]/30 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
        </div>
      </div>
    </div>
  );
}

export default Experience;
